static int g_pass = 0, g_fail = 0;
#define CHECK(c) do { if (c) ++g_pass; else { ++g_fail; std::printf("FAIL %s:%d: %s\n", __FILE__, __LINE__, #c); } } while (0)
#define CHECKM(c, m) do { if (c) ++g_pass; else { ++g_fail; std::printf("FAIL %s:%d: %s [%s]\n", __FILE__, __LINE__, #c, std::string(m).c_str()); } } while (0)

static const std::string D = "tests/data/cad/odb_cases/";

static bool near(Vec2 a, Vec2 b, double t = 1e-3) { return std::fabs(a.x - b.x) < t && std::fabs(a.y - b.y) < t; }
static bool has_warn(const io::CadImportResult& r, const std::string& s) {
    for (auto& w : r.warnings) if (w.find(s) != std::string::npos) return true;
    return false;
}
static double nrm(double a) { a = std::fmod(a, 360.0); if (a < 0) a += 360; if (a > 359.9995) a = 0; return a; }
static void dump(const io::CadImportResult& r) { std::printf("   %s\n", r.describe().c_str()); for (auto& w : r.warnings) std::printf("     warn: %s\n", w.c_str()); }

static void test_lzw() {
    std::mt19937 rng(7);
    for (int round = 0; round < 6; ++round) {
        std::vector<uint8_t> d;
        const size_t n = round == 0 ? 0 : round == 1 ? 1 : (size_t)1 << (8 + round * 2);
        for (size_t i = 0; i < n; ++i) d.push_back(round % 2 ? (uint8_t)rng() : (uint8_t)("ODB++ features P 1 2 3\n"[i % 23]));
        for (int bits : {9, 12, 16}) {
            auto z = io::lzw_compress(d.data(), d.size(), bits);
            std::vector<uint8_t> back;
            std::string err;
            CHECKM(io::lzw_decompress(z.data(), z.size(), back, err), err);
            CHECK(back == d);
        }
    }
    std::vector<uint8_t> out;
    std::string err;
    // corrupt input reports an error instead of crashing
    std::vector<uint8_t> bad = {0x1f, 0x9d, 0x90, 0xff, 0xff, 0xff, 0xff};
    CHECK(!io::lzw_decompress(bad.data(), bad.size(), out, err));
}

static void test_panel() {
    std::string err;
    io::OdbJobInfo info;
    CHECKM(io::odb_scan(D + "panel_mm.tgz", info, err), err);
    std::printf("%s", io::odb_describe(info).c_str());
    CHECK(info.steps.size() == 3);
    CHECK(info.compressed_members >= 2);
    CHECK(info.recommended == 1 && info.steps[1].name == "pcb");
    CHECK(info.recommend_reason.find("panel") != std::string::npos);
    CHECK(info.steps[0].kind == "panel" && info.steps[0].instances == 3);
    CHECK(info.steps[0].leaf_comps == 6 * 3 + 2);
    CHECK(info.steps[1].comp_top == 4 && info.steps[1].comp_bot == 2);
    CHECK(info.steps[2].kind == "coupon");
    CHECK(info.steps[0].has_profile && std::fabs(info.steps[0].w - 250) < 1e-6);
    CHECK(info.units == "mm");

    {   // default: recommended single board, .Z members decoded, PRP -> part fields
        Project p;
        io::CadImportResult r;
        io::CadImportOptions o;
        CHECKM(io::import_odbpp(D + "panel_mm.tgz", p, o, r, err), err);
        dump(r);
        CHECK(r.components == 6 && p.images.size() == 1);
        const Component* u1 = p.find_ref("U1");
        CHECK(u1 && near(u1->pos, {30, 22}) && u1->side == Side::Bottom && std::fabs(nrm(u1->rot) - 90) < 1e-6);
        CHECK(p.parts.count("LM358") && p.parts["LM358"].manf_pn == "MPN-LM358" && p.parts["LM358"].description == "SOIC8 LM358");
        CHECK(has_warn(r, "ASSEMBLY_NOTE"));
        CHECK(has_warn(r, "compressed member"));
        CHECK(has_warn(r, "rotation convention verified"));
        CHECK(has_warn(r, "chosen automatically"));
    }
    {   // panel with step-repeat as images
        Project p;
        io::CadImportResult r;
        io::CadImportOptions o;
        o.step = "panel|images";
        CHECKM(io::import_odbpp(D + "panel_mm.tgz", p, o, r, err), err);
        dump(r);
        CHECK(r.components == 6 + 2);
        CHECK(p.images.size() == 3);
        const Component* r1 = p.find_ref("R1");
        CHECK(r1 && near(r1->pos, {20, 20}));
        if (r1 && p.images.size() == 3) {
            CHECK(near(p.image_xform(1).apply(r1->pos), {80, 20}));
            // ANGLE=90 (clockwise) instance at (180,60): child (10,10) -> (190,50)
            CHECK(near(p.image_xform(2).apply(r1->pos), {190, 50}));
            CHECK(std::fabs(nrm(p.images[2].rot) - 270) < 1e-6);
        }
        const Component* pf = p.find_ref("PFID2");
        CHECK(pf && pf->feature == Feature::Fiducial && near(pf->pos, {247, 97}));
        CHECK(!p.panel_frame.empty());
        CHECK(has_warn(r, "3 images"));
    }
    {   // flat expansion
        Project p;
        io::CadImportResult r;
        io::CadImportOptions o;
        o.step = "panel|flat";
        CHECKM(io::import_odbpp(D + "panel_mm.tgz", p, o, r, err), err);
        CHECK(r.components == 6 * 3 + 2);
        const Component* c = p.find_ref("R1_3");
        CHECK(c && near(c->pos, {190, 50}) && std::fabs(nrm(c->rot) - 270) < 1e-6);
    }
    {   // unknown step: error lists the steps
        Project p;
        io::CadImportResult r;
        io::CadImportOptions o;
        o.step = "nope";
        CHECK(!io::import_odbpp(D + "panel_mm", p, o, r, err));
        CHECK(err.find("panel") != std::string::npos && err.find("pcb") != std::string::npos);
    }
}

static void test_geometry_only() {
    std::string err;
    io::OdbJobInfo info;
    CHECKM(io::odb_scan(D + "geom_nested.zip", info, err), err);
    CHECK(info.container.find("nested") != std::string::npos);
    CHECK(info.recommend_reason.find("geometry only") != std::string::npos);
    Project p;
    io::CadImportResult r;
    io::CadImportOptions o;
    CHECKM(io::import_odbpp(D + "geom_nested.zip", p, o, r, err), err);
    dump(r);
    CHECK(r.components == 0);
    CHECK(has_warn(r, "No placements"));
    CHECK(has_warn(r, "weird_user_sym"));
    CHECK(!p.board_frame.empty());
    int copper = 0, silk = 0, drill = 0;
    for (auto& L : p.layers) {
        gerber::Layer gl;
        gerber::ParseOptions po;
        std::string e2;
        const bool ok = gerber::parse(L.content, po, gl, e2);
        CHECKM(ok, L.name + ": " + e2);
        if (L.role == LayerRole::Copper) {
            ++copper;
            CHECK(gl.flash_count() >= 3);   // rect, rect@90, square (oval@30 -> polygon, user symbol skipped)
            CHECK(gl.region_count() >= 2);   // surface island + rotated oval polygon
            CHECK(gl.draw_count() >= 2);
            // pad 0.5,0.5 inch = 12.7 mm, rect 60x40 mil
            CHECK(gl.extent.x0 < 2.6 && gl.extent.x1 > 27.9);
        }
        if (L.role == LayerRole::Silk) ++silk;
        if (L.role == LayerRole::Drill) {
            ++drill;
            CHECK(gl.excellon && gl.flash_count() == 2);
            CHECK(L.content.find("C1.000") != std::string::npos && L.content.find("C0.508") != std::string::npos);
        }
    }
    CHECKM(copper == 1 && silk == 1 && drill == 1, std::to_string(copper) + "/" + std::to_string(silk) + "/" + std::to_string(drill));
}

static void test_conventions() {
    std::string err;
    {   // CCW exporter in a .tar.Z, "# CMP" comments
        Project p;
        io::CadImportResult r;
        io::CadImportOptions o;
        CHECKM(io::import_odbpp(D + "ccw.tar.Z", p, o, r, err), err);
        dump(r);
        CHECK(r.components == 6);
        CHECK(has_warn(r, "counter-clockwise"));
        const Component* c1 = p.find_ref("C1");
        const Component* j1 = p.find_ref("J1");
        const Component* u1 = p.find_ref("U1");
        CHECK(c1 && std::fabs(nrm(c1->rot) - 90) < 1e-6);
        CHECK(j1 && std::fabs(nrm(j1->rot) - 270) < 1e-6);
        CHECK(u1 && std::fabs(nrm(u1->rot) - 90) < 1e-6 && u1->side == Side::Bottom);
    }
    {   // no eda/data, legacy "U MM", .gz member: packages derived from toeprints
        Project p;
        io::CadImportResult r;
        io::CadImportOptions o;
        CHECKM(io::import_odbpp(D + "noeda", p, o, r, err), err);
        dump(r);
        CHECK(r.components == 6);
        const Component* r1 = p.find_ref("R1");
        CHECK(r1 && near(r1->pos, {10, 10}));
        const Package* pk = r1 ? p.package_of(*r1) : nullptr;
        CHECK(pk && pk->pads.size() == 2);
        if (pk && pk->pads.size() == 2) CHECK(std::fabs(std::fabs(pk->pads[0].pos.x) - 0.95) < 1e-3);
        const Component* u1 = p.find_ref("U1");
        CHECK(u1 && p.package_of(*u1) && p.package_of(*u1)->pads.size() == 8);
        // bottom pin 1 of U1 is at local (-2.7, 1.905): through the model transform it must land on its toeprint
        if (u1 && p.package_of(*u1)) {
            Vec2 a = p.comp_xform(*u1).apply(p.package_of(*u1)->pads[0].pos);
            CHECK(near(a, {30 - 1.905, 22 + 2.7}, 2e-3));
        }
    }
    {   // wrong step: panel has a profile only -> imported, explicit hint to use 'pcb'
        io::OdbJobInfo info;
        CHECKM(io::odb_scan(D + "wrongstep", info, err), err);
        CHECK(info.recommended == 1);
        Project p;
        io::CadImportResult r;
        io::CadImportOptions o;
        o.step = "panel";
        CHECKM(io::import_odbpp(D + "wrongstep", p, o, r, err), err);
        dump(r);
        CHECK(r.components == 0);
        CHECK(has_warn(r, "Step 'pcb' has 6 components"));
    }
}

static void test_board_image() {
    // board points of a 100 x 80 board seen by a camera: synthetic homography
    const double Ht[9] = {0.05, 0.004, 10, 0.002, -0.06, 90, 0.00001, 0.00002, 1};
    BoardImage bi;
    bi.px_w = 2000; bi.px_h = 1500;
    std::vector<Vec2> img = {{100, 120}, {1900, 80}, {1850, 1400}, {150, 1450}, {1000, 700}};
    for (auto& u : img) bi.pairs.push_back({u, h_apply(Ht, u)});
    std::string err;
    // 4-point perspective: exact on the picks and on any other point
    bi.pairs.resize(4);
    CHECKM(calibrate(bi, err), err);
    CHECK(bi.calib == 4 && bi.rms_mm < 1e-6);
    CHECK(near(h_apply(bi.H, {1000, 700}), h_apply(Ht, {1000, 700}), 1e-6));
    // 5 points: least squares, still exact for consistent data
    bi.pairs.push_back({img[4], h_apply(Ht, img[4])});
    CHECKM(calibrate(bi, err), err);
    CHECK(bi.rms_mm < 1e-6);
    // inverse
    double Hi[9];
    CHECK(h_invert(bi.H, Hi));
    CHECK(near(h_apply(Hi, h_apply(bi.H, {321, 654})), {321, 654}, 1e-6));
    // 2-point similarity: AOI image at 20 px/mm, rotated 30 deg, Y down -> board Y up
    const double s = 1.0 / 20, th = 30 * kPi / 180;
    auto sim = [&](Vec2 u) { Vec2 f{u.x, -u.y}; return Vec2{s * (f.x * std::cos(th) - f.y * std::sin(th)) + 5, s * (f.x * std::sin(th) + f.y * std::cos(th)) + 7}; };
    BoardImage b2;
    b2.px_w = 1000; b2.px_h = 800;
    b2.pairs = {{{50, 60}, sim({50, 60})}, {{900, 700}, sim({900, 700})}};
    CHECKM(calibrate(b2, err), err);
    CHECK(b2.calib == 2 && near(h_apply(b2.H, {400, 100}), sim({400, 100}), 1e-9));
    // known dimensions: fiducials 80 mm apart picked 1600 px apart -> 20 px/mm
    BoardImage b3;
    b3.px_w = 2000; b3.px_h = 1000;
    b3.pairs = {{{200, 900}, {5, 5}}, {{1800, 900}, {85, 5}}};
    CHECKM(calibrate(b3, err), err);
    Vec2 c = h_apply(b3.H, {1000, 500});   // 400 px above the fiducial line -> +20 mm
    CHECK(near(c, {45, 25}, 1e-9));
    // mirrored (bottom side scanned face down)
    b3.mirrored = true;
    CHECKM(calibrate(b3, err), err);
    CHECK(near(h_apply(b3.H, {200, 900}), {5, 5}, 1e-9) && near(h_apply(b3.H, {1800, 900}), {85, 5}, 1e-9));
    CHECK(near(h_apply(b3.H, {1000, 500}), {45, -15}, 1e-9));   // mirrored: image 'up' lands below the fiducial line
    // 1 point: translation keeps scale
    BoardImage b4 = b2;
    b4.pairs = {{{50, 60}, {0, 0}}};
    CHECKM(calibrate(b4, err), err);
    CHECK(near(h_apply(b4.H, {50, 60}), {0, 0}, 1e-9));
    CHECK(std::fabs(dist(h_apply(b4.H, {50, 60}), h_apply(b4.H, {70, 60})) - 1.0) < 1e-9);
    // degenerate inputs
    BoardImage b5;
    b5.pairs = {{{0, 0}, {0, 0}}, {{10, 0}, {1, 0}}, {{20, 0}, {2, 0}}, {{30, 0}, {3, 0}}};
    CHECK(!calibrate(b5, err) && !err.empty());
    b5.pairs = {{{5, 5}, {0, 0}}, {{5, 5}, {1, 1}}};
    CHECK(!calibrate(b5, err));
    // default fit keeps aspect and Y up
    BoardImage b6;
    b6.px_w = 200; b6.px_h = 100;
    BBox bb; bb.add({0, 0}); bb.add({100, 100});
    fit_to_box(b6, bb);
    Vec2 cr[4];
    image_corners(b6, cr);
    CHECK(near(cr[3], {0, 25}) && near(cr[1], {100, 75}));
    // PPM loader + probe
    std::string ppm = "P6\n# test\n3 2\n255\n";
    for (int i = 0; i < 6; ++i) { ppm += (char)(i * 40); ppm += (char)10; ppm += (char)200; }
    int w = 0, h = 0;
    std::vector<uint8_t> rgba;
    CHECKM(decode_pnm((const uint8_t*)ppm.data(), ppm.size(), w, h, rgba, err), err);
    CHECK(w == 3 && h == 2 && rgba.size() == 24 && rgba[4] == 40 && rgba[7] == 255);
    CHECK(probe_image_size((const uint8_t*)ppm.data(), ppm.size(), w, h) && w == 3 && h == 2);
    const uint8_t png[] = {0x89, 'P', 'N', 'G', 13, 10, 26, 10, 0, 0, 0, 13, 'I', 'H', 'D', 'R', 0, 0, 0x0F, 0xA0, 0, 0, 0x0B, 0xB8};
    CHECK(probe_image_size(png, sizeof png, w, h) && w == 4000 && h == 3000);
    // base64
    std::vector<uint8_t> raw(rgba.begin(), rgba.end()), back;
    for (size_t n = 0; n < 5; ++n) {
        std::vector<uint8_t> v(raw.begin(), raw.begin() + n + 10);
        CHECK(base64_decode(base64_encode(v), back) && back == v);
    }
    // project round trip (embedded image, transform, pairs, flags) + source refs
    Project p;
    BoardImage e = b3;
    e.name = "aoi"; e.path = "C:/img/aoi.ppm";
    e.data.assign(ppm.begin(), ppm.end());
    e.opacity = 0.25f; e.locked = true; e.side = 1;
    p.board_images.push_back(e);
    Project::SourceRef sr;
    sr.path = "job.tgz"; sr.importer = "odbpp"; sr.settings["step"] = "pcb"; sr.warnings = {"w1"};
    p.sources.push_back(sr);
    Project q;
    CHECKM(project_from_json(project_to_json(p), q, err), err);
    CHECK(q.board_images.size() == 1 && q.board_images[0].data == e.data && q.board_images[0].locked && q.board_images[0].side == 1);
    CHECK(q.board_images.size() == 1 && std::fabs(q.board_images[0].opacity - 0.25f) < 1e-6 && q.board_images[0].pairs.size() == 2);
    if (!q.board_images.empty()) CHECK(near(h_apply(q.board_images[0].H, {1000, 500}), h_apply(e.H, {1000, 500}), 1e-9));
    CHECK(q.sources.size() == 1 && q.sources[0].settings["step"] == "pcb" && q.sources[0].warnings.size() == 1);
}

// ---------------------------------------------------------------------------
// Round 10 (REVIEW_V9 §6): package outlines, origins, units, classification,
// rescale. Synthetic jobs written to build/tests/odb_r10/ (no customer data).
// ---------------------------------------------------------------------------
#include <filesystem>
#include <fstream>
#include "../src/io/cad_common.h"

static void wfile(const std::string& path, const std::string& text) {
    std::filesystem::create_directories(std::filesystem::path(path).parent_path());
    std::ofstream(path, std::ios::binary) << text;
}

// One-step job "pcb": 60 x 40 board; J2 = connector whose body overhangs the
// board edge (outline to y = 44); U34 = TO-92 style package whose outline is a
// flat side + an arc (OC); SW1 = switch with an off-centre origin; R1 = package
// with only a PKG extent; Q1 = package with neither (derived from pads).
static std::string make_job(const std::string& dir, const std::string& units, double s, bool with_eda, bool with_comps) {
    auto n = [&](double v) { char b[32]; std::snprintf(b, sizeof b, "%.6f", v * s); return std::string(b); };
    const std::string U = units.empty() ? "" : "UNITS=" + units + "\n";
    wfile(dir + "/matrix/matrix", "STEP {\n COL=1\n NAME=PCB\n}\nLAYER {\n ROW=1\n CONTEXT=BOARD\n TYPE=COMPONENT\n NAME=COMP_+_TOP\n POLARITY=POSITIVE\n}\n"
                                  "LAYER {\n ROW=2\n CONTEXT=BOARD\n TYPE=SIGNAL\n NAME=TOP\n POLARITY=POSITIVE\n}\n");
    wfile(dir + "/misc/info", "JOB_NAME=r10\nODB_VERSION_MAJOR=7\n" + U);
    wfile(dir + "/steps/pcb/profile", U + "S P 0\nOB " + n(0) + " " + n(0) + " I\nOS " + n(60) + " " + n(0) + "\nOS " + n(60) + " " + n(40) +
                                      "\nOS " + n(0) + " " + n(40) + "\nOE\nSE\n");
    wfile(dir + "/steps/pcb/layers/top/features", U + "$0 r500\n#\nP " + n(10) + " " + n(10) + " 0 P 0 0\n");
    if (with_eda) {
        std::string e = U + "# eda\n";
        // 0 J2: pins at y = 0, body -5..5 x -2..4 (overhang beyond board edge when placed at y = 39)
        e += "PKG CONN2 " + n(2.54) + " " + n(-5) + " " + n(-2) + " " + n(5) + " " + n(4) + ";;ID=1\n";
        e += "CT\nOB " + n(-5) + " " + n(-2) + " I\nOS " + n(5) + " " + n(-2) + "\nOS " + n(5) + " " + n(4) + "\nOS " + n(-5) + " " + n(4) + "\nOE\nCE\n";
        e += "PIN 1 S " + n(-1.27) + " 0 0 E S\nRC " + n(-1.77) + " " + n(-0.5) + " " + n(1) + " " + n(1) + "\n";
        e += "PIN 2 S " + n(1.27) + " 0 0 E S\nRC " + n(0.77) + " " + n(-0.5) + " " + n(1) + " " + n(1) + "\n";
        // 1 U34: TO-92: flat side y = -1, arc through (0, 2.6) from (-2,-1) to (2,-1) around (0,0.5) clockwise
        e += "PKG TO92 " + n(1.27) + " " + n(-2.5) + " " + n(-1) + " " + n(2.5) + " " + n(3) + "\n";
        e += "CT\nOB " + n(-2) + " " + n(-1) + " I\nOS " + n(2) + " " + n(-1) + "\nOC " + n(-2) + " " + n(-1) + " 0 " + n(0.5) + " N\nOE\nCE\n";
        e += "PIN 1 T " + n(-1.27) + " 0 0 E T\nCR " + n(-1.27) + " 0 " + n(0.4) + "\n";
        e += "PIN 2 T 0 0 0 E T\nCR 0 0 " + n(0.4) + "\n";
        e += "PIN 3 T " + n(1.27) + " 0 0 E T\nCR " + n(1.27) + " 0 " + n(0.4) + "\n";
        // 2 SW: origin off-centre (pins at x 3..7)
        e += "PKG SW " + n(4) + " " + n(2) + " " + n(-1) + " " + n(8) + " " + n(1) + "\nRC " + n(2) + " " + n(-1) + " " + n(6) + " " + n(2) + "\n";
        e += "PIN 1 S " + n(3) + " 0 0 E S\nRC " + n(2.5) + " " + n(-0.5) + " " + n(1) + " " + n(1) + "\n";
        e += "PIN 2 S " + n(7) + " 0 0 E S\nRC " + n(6.5) + " " + n(-0.5) + " " + n(1) + " " + n(1) + "\n";
        // 3 R: extent only
        e += "PKG R0603 " + n(1.6) + " " + n(-1.2) + " " + n(-0.6) + " " + n(1.2) + " " + n(0.6) + "\n";
        e += "PIN 1 S " + n(-0.8) + " 0 0 E S\nRC " + n(-1.2) + " " + n(-0.4) + " " + n(0.8) + " " + n(0.8) + "\n";
        e += "PIN 2 S " + n(0.8) + " 0 0 E S\nRC " + n(0.4) + " " + n(-0.4) + " " + n(0.8) + " " + n(0.8) + "\n";
        // 4 Q: no extent, no outline
        e += "PKG SOT\n";
        e += "PIN 1 S " + n(-1) + " 0 0 E S\nRC " + n(-1.3) + " " + n(-0.3) + " " + n(0.6) + " " + n(0.6) + "\n";
        e += "PIN 2 S " + n(1) + " 0 0 E S\nRC " + n(0.7) + " " + n(-0.3) + " " + n(0.6) + " " + n(0.6) + "\n";
        wfile(dir + "/steps/pcb/eda/data", e);
    }
    if (with_comps) {
        std::string c = U;
        c += "CMP 0 " + n(30) + " " + n(39) + " 0 N J2 CONN-2\nPRP PART_NUMBER 'CONN-2'\n";
        c += "CMP 1 " + n(10) + " " + n(20) + " 90 N U34 DS18B20\n";
        c += "CMP 2 " + n(40) + " " + n(14.17) + " 0 N SW1 SW-1\n";
        c += "CMP 3 " + n(20) + " " + n(10) + " 0 N R1 10K\n";
        c += "CMP 4 " + n(50) + " " + n(10) + " 0 N Q1 BC847\n";
        wfile(dir + "/steps/pcb/layers/comp_+_top/components", c);
    }
    return dir;
}

static const GPrim* first_kind(const Package& p, GKind k) { for (auto& g : p.body) if (g.kind == k) return &g; return nullptr; }

static void test_r10_outlines_origin() {
    std::printf("-- r10 outlines / origin\n");
    const std::string dir = make_job("build/tests/odb_r10/mm", "MM", 1.0, true, true);
    Project p;
    io::CadImportOptions o;
    io::CadImportResult r;
    std::string err;
    CHECKM(io::import_odbpp(dir, p, o, r, err), err);
    dump(r);
    CHECK(r.status == io::CadImportStatus::Complete);
    CHECK(r.body_cad == 3 && r.body_extent == 1 && r.body_derived == 1);
    CHECK(p.packages.count("CONN2") && p.packages["CONN2"].body_source == "cad");
    if (p.packages.count("CONN2")) {
        BBox b = gprims_bbox(p.packages["CONN2"].body);
        CHECK(std::fabs(b.y1 - 4) < 0.06 && std::fabs(b.x0 + 5) < 0.06);         // true body, not pin-bounded
        // J2 placed at y = 39: body reaches y = 43 > board edge 40 (overhang kept)
        CHECK(39 + b.y1 > 40.5);
    }
    CHECK(p.packages.count("TO92") && p.packages["TO92"].body_source == "cad");
    if (p.packages.count("TO92")) {
        const GPrim* a = first_kind(p.packages["TO92"], GKind::Arc);
        CHECK(a != nullptr);
        if (a) {
            CHECK(near(a->pts[0], {0, 0.5}) && std::fabs(a->radius - 2.5) < 1e-6);
            CHECK(a->a1 > 0 && a->a1 < 360);                         // CCW (N flag) sweep from (2,-1) to (-2,-1) via the top
            const double mid = deg2rad(a->a0 + a->a1 / 2);
            CHECK(std::fabs(a->pts[0].y + a->radius * std::sin(mid) - 3.0) < 1e-6);   // apex (0, 3)
        }
        CHECK(first_kind(p.packages["TO92"], GKind::Line) != nullptr);
    }
    CHECK(p.packages.count("R0603") && p.packages["R0603"].body_source == "cad_extent");
    CHECK(p.packages.count("SOT") && p.packages["SOT"].body_source == "pads");
    // SW1: imported origin preserved (pads off-centre, centroid = CMP position)
    const Component* sw = nullptr;
    for (auto& c : p.comps) if (c.ref == "SW1") sw = &c;
    CHECK(sw && near(sw->pos, {40, 14.17}));
    if (p.packages.count("SW")) {
        auto& pk = p.packages["SW"];
        CHECK(pk.pads.size() == 2 && near(pk.pads[0].pos, {3, 0}) && near(pk.pads[1].pos, {7, 0}));
        CHECK(pk.body_source == "cad" && std::fabs(gprims_bbox(pk.body).x0 - 2) < 0.06);
    }
    // provenance survives a project round trip
    Project q;
    CHECKM(project_from_json(project_to_json(p), q, err), err);
    CHECK(q.packages["TO92"].body_source == "cad" && q.packages["SOT"].body_source == "pads" && q.packages["R0603"].body_source == "cad_extent");
    // scan reports outline availability + units evidence
    io::OdbJobInfo info;
    CHECKM(io::odb_scan(dir, info, err), err);
    CHECK(info.steps.size() == 1 && info.steps[0].pkg_outlines == 3 && info.steps[0].pkg_extents == 1 && info.steps[0].pkgs == 5);
}

static void test_r10_units() {
    std::printf("-- r10 units\n");
    std::string err;
    // inch job: declared + evidence
    {
        const std::string dir = make_job("build/tests/odb_r10/inch", "INCH", 1 / 25.4, true, true);
        io::OdbJobInfo info;
        CHECKM(io::odb_scan(dir, info, err), err);
        CHECK(!info.steps.empty() && info.steps[0].units_declared && std::fabs(info.steps[0].units_k - 25.4) < 1e-9 && !info.steps[0].units_conflict);
        CHECK(!info.steps.empty() && std::fabs(info.steps[0].w - 60) < 1e-3);
        CHECK(info.job_units.find("INCH") != std::string::npos);
        Project p; io::CadImportOptions o; io::CadImportResult r;
        CHECKM(io::import_odbpp(dir, p, o, r, err), err);
        CHECK(r.units == "inch" && r.units_evidence.find("profile: UNITS=INCH") != std::string::npos);
        const Component* sw = nullptr;
        for (auto& c : p.comps) if (c.ref == "SW1") sw = &c;
        CHECK(sw && near(sw->pos, {40, 14.17}, 1e-4));
    }
    // mm values but no UNITS declared: default inch -> 25.4x too big; detected + warned; override fixes it
    {
        const std::string dir = make_job("build/tests/odb_r10/undecl", "", 1.0, true, true);
        io::OdbJobInfo info;
        CHECKM(io::odb_scan(dir, info, err), err);
        CHECK(!info.steps.empty() && !info.steps[0].units_declared && std::fabs(info.steps[0].w - 60 * 25.4) < 1e-6);
        CHECK(!io::odb_unit_warnings(info.steps[0].w, info.steps[0].h, 0, 5).empty());     // board > 1 m
        Project p; io::CadImportOptions o; io::CadImportResult r;
        CHECKM(io::import_odbpp(dir, p, o, r, err), err);
        CHECK(has_warn(r, "check units") && has_warn(r, "larger than 1 m"));
        Project p2; io::CadImportResult r2; o.units = "mm";
        CHECKM(io::import_odbpp(dir, p2, o, r2, err), err);
        CHECK(!has_warn(r2, "larger than 1 m") && has_warn(r2, "unit conversion override"));
        BBox fb; for (auto& pl : p2.board_frame) for (auto& q : pl) fb.add(q);
        CHECK(std::fabs(fb.w() - 60) < 1e-6 && std::fabs(fb.h() - 40) < 1e-6);
        CHECK(p2.packages.count("TO92") && std::fabs(p2.packages["TO92"].pads[0].w - 0.8) < 1e-6);       // pad sizes follow
        // drill/copper symbol sizes follow the forced unit (r500 = 500 micron)
        bool lay = false;
        for (auto& L : p2.layers) if (L.content.find("C,0.5") != std::string::npos) lay = true;
        (void)lay;
        // arbitrary scale is separate from the unit
        Project p3; io::CadImportResult r3; o.units = "mm"; o.scale = 2.0;
        CHECKM(io::import_odbpp(dir, p3, o, r3, err), err);
        const Component* sw = nullptr;
        for (auto& c : p3.comps) if (c.ref == "SW1") sw = &c;
        CHECK(sw && near(sw->pos, {80, 28.34}, 1e-6));
        CHECK(r3.units.find("user scale") != std::string::npos);
        CHECK(io::units_override_mm("0.1mm") == 0.1 && io::units_override_mm("mil") == kMmPerMil && io::units_override_mm("0.5") == 0.5 && io::units_override_mm("auto") == 0);
    }
    // tiny board (inch values read as mm) and placements outside the profile
    CHECK(!io::odb_unit_warnings(2.3, 1.5, 0, 10).empty());
    CHECK(io::odb_unit_warnings(60, 40, 0, 10).empty());
    CHECK(!io::odb_unit_warnings(60, 40, 3, 10).empty());
}

