static void test_r10_rescale() {
    std::printf("-- r10 rescale\n");
    std::string err;
    const std::string dir = make_job("build/tests/odb_r10/resc", "", 1.0, true, true);   // read as inch: 25.4x too big
    Project p; io::CadImportOptions o; io::CadImportResult r;
    o.step = "pcb|layers";
    CHECKM(io::import_odbpp(dir, p, o, r, err), err);
    CHECK(!p.layers.empty());
    Project ref; o.units = "mm"; io::CadImportResult r2;
    CHECKM(io::import_odbpp(dir, ref, o, r2, err), err);
    std::vector<std::string> notes;
    const int nl = io::rescale_project(p, 1 / 25.4, notes);
    for (auto& n : notes) std::printf("   note: %s\n", n.c_str());
    CHECK(nl == (int)p.layers.size() && notes.empty());
    for (auto& c : p.comps)
        for (auto& c2 : ref.comps) if (c.ref == c2.ref) CHECKM(near(c.pos, c2.pos, 1e-6), c.ref);
    CHECK(near(p.packages["SW"].pads[1].pos, ref.packages["SW"].pads[1].pos, 1e-9));
    CHECK(std::fabs(gprims_bbox(p.packages["TO92"].body).y1 - gprims_bbox(ref.packages["TO92"].body).y1) < 1e-9);
    BBox a, b;
    for (auto& pl : p.board_frame) for (auto& q : pl) a.add(q);
    for (auto& pl : ref.board_frame) for (auto& q : pl) b.add(q);
    CHECK(std::fabs(a.w() - b.w()) < 1e-6);
    // layer geometry identical after parse
    for (size_t i = 0; i < p.layers.size() && i < ref.layers.size(); ++i) {
        gerber::Layer la, lb;
        gerber::ParseOptions po;
        std::string e1, e2;
        CHECK(gerber::parse(p.layers[i].content, po, la, e1) && gerber::parse(ref.layers[i].content, po, lb, e2));
        CHECKM(std::fabs(la.extent.w() - lb.extent.w()) < 1e-3 && std::fabs(la.extent.x0 - lb.extent.x0) < 1e-3, p.layers[i].name);
    }
    // RS-274X text scaling: coordinates, apertures, comments untouched, macro refused
    std::string g = "%FSLAX46Y46*%\n%MOMM*%\n%ADD10C,0.500000*%\n%ADD11R,1.0X2.0*%\n%ADD12P,1.0X6X30*%\nG04 X99 comment*\nD10*\nX1000000Y-2000000D03*\nG03X0Y0I500000J0D01*\nM02*\n";
    CHECKM(io::scale_rs274x(g, 2.0, err), err);
    CHECK(g.find("C,1.000000") != std::string::npos && g.find("R,2.000000X4.000000") != std::string::npos && g.find("P,2.000000X6X30") != std::string::npos);
    CHECK(g.find("X2000000Y-4000000D03") != std::string::npos && g.find("I1000000J0") != std::string::npos && g.find("G04 X99 comment") != std::string::npos);
    std::string m = "%FSLAX24Y24*%\n%AMBOX*21,1,$1,$2,0,0,0*%\n";
    CHECK(!io::scale_rs274x(m, 2.0, err));
    std::string x = "M48\nMETRIC,LZ,000.000\nT01C0.300\n%\nG90\nT01\nX1.000Y2.000\nM30\n";
    CHECKM(io::scale_excellon(x, 10, err), err);
    CHECK(x.find("T01C3.000000") != std::string::npos && x.find("X10.000000Y20.000000") != std::string::npos);
}

// R12: user-defined symbols (nested features, rotated / mirrored placement) + rounded / chamfered rects
static void test_r12_user_symbols() {
    const std::string sym = "UNITS=MM\n$0 r0.2\nS P 0\nOB -1 -0.5 I\nOS 1 -0.5\nOS 1 0.5\nOS -1 0.5\nOE\nSE\nL -1 0 1 0 0 P 0\n";
    const std::string feat = "UNITS=MM\n$0 my_sym\n$1 rect2x1xr0.25\n$2 rect2x1xc0.2x13\n$3 nosuch\n"
                             "P 10 10 0 P 0 0\nP 20 10 0 P 0 8 90\nP 30 10 1 P 0 0\nP 40 10 2 P 0 1\nP 50 10 3 P 0 0\n";
    io::OdbSymbolLookup look = [&](const std::string& n, std::string& out) { if (n != "my_sym") return false; out = sym; return true; };
    std::string g, notes;
    CHECK(io::odb_features_to_gerber(feat, g, notes, &look));
    CHECKM(notes.find("nosuch x1") != std::string::npos && notes.find("my_sym") == std::string::npos, notes);
    CHECKM(notes.find("2 user-defined symbol instance") != std::string::npos, notes);
    CHECKM(notes.find("square corners") == std::string::npos, notes);
    gerber::Layer L; std::string e; gerber::ParseOptions po;
    CHECK(gerber::parse(g, po, L, e));
    // second instance rotated 90 deg cw: the 2 x 1 body becomes 1 wide x 2 tall around (20,10)
    BBox b2; for (auto& o : L.objs) { BBox ob = gerber::object_bbox(L, o); if (ob.center().x > 18 && ob.center().x < 22) b2.add(ob); }
    CHECKM(std::fabs(b2.w() - 1.0) < 0.25 && std::fabs(b2.h() - 2.0) < 0.25, std::to_string(b2.w()) + "x" + std::to_string(b2.h()));
    // without a lookup (old API): reported as unsupported
    CHECK(io::odb_features_to_gerber(feat, g, notes) && notes.find("my_sym x2") != std::string::npos);
}

// ---------------------------------------------------------------------------
// R14: ODB++ opened straight from .tar / .tar.gz / .zip built in memory from the synthetic
// panel_mm job (no customer data), Allegro "???" part placeholders, archive hardening.
// ---------------------------------------------------------------------------
static void tar_put(std::vector<uint8_t>& t, const std::string& name, const std::string& data, char type = '0') {
    uint8_t h[512] = {};
    std::memcpy(h, name.data(), std::min<size_t>(name.size(), 100));
    std::snprintf((char*)h + 100, 8, "%07o", 0644);
    std::snprintf((char*)h + 124, 12, "%011o", (unsigned)data.size());
    std::snprintf((char*)h + 136, 12, "%011o", 0u);
    h[156] = (uint8_t)type;
    std::memcpy(h + 257, "ustar\0" "00", 8);
    std::memset(h + 148, ' ', 8);
    unsigned sum = 0;
    for (int i = 0; i < 512; ++i) sum += h[i];
    std::snprintf((char*)h + 148, 8, "%06o", sum);
    t.insert(t.end(), h, h + 512);
    t.insert(t.end(), data.begin(), data.end());
    t.resize((t.size() + 511) & ~size_t(511), 0);
}
static void le16(std::vector<uint8_t>& v, unsigned x) { v.push_back(uint8_t(x)); v.push_back(uint8_t(x >> 8)); }
static void le32(std::vector<uint8_t>& v, uint32_t x) { le16(v, x & 0xFFFF); le16(v, x >> 16); }
static std::vector<uint8_t> zip_stored(const std::vector<std::pair<std::string, std::string>>& files) {
    std::vector<uint8_t> z, cd;
    for (auto& f : files) {
        const uint32_t off = (uint32_t)z.size();
        const uint32_t crc = io::crc32_ieee((const uint8_t*)f.second.data(), f.second.size());
        le32(z, 0x04034b50); le16(z, 20); le16(z, 0); le16(z, 0); le32(z, 0); le32(z, crc);
        le32(z, (uint32_t)f.second.size()); le32(z, (uint32_t)f.second.size()); le16(z, (unsigned)f.first.size()); le16(z, 0);
        z.insert(z.end(), f.first.begin(), f.first.end()); z.insert(z.end(), f.second.begin(), f.second.end());
        le32(cd, 0x02014b50); le16(cd, 20); le16(cd, 20); le16(cd, 0); le16(cd, 0); le32(cd, 0); le32(cd, crc);
        le32(cd, (uint32_t)f.second.size()); le32(cd, (uint32_t)f.second.size()); le16(cd, (unsigned)f.first.size());
        le16(cd, 0); le16(cd, 0); le16(cd, 0); le16(cd, 0); le32(cd, 0); le32(cd, off);
        cd.insert(cd.end(), f.first.begin(), f.first.end());
    }
    const uint32_t cdo = (uint32_t)z.size();
    z.insert(z.end(), cd.begin(), cd.end());
    le32(z, 0x06054b50); le16(z, 0); le16(z, 0); le16(z, (unsigned)files.size()); le16(z, (unsigned)files.size());
    le32(z, (uint32_t)cd.size()); le32(z, cdo); le16(z, 0);
    return z;
}
static bool write_bin(const std::string& path, const std::vector<uint8_t>& d) {
    std::ofstream f(path, std::ios::binary);
    f.write((const char*)d.data(), (std::streamsize)d.size());
    return (bool)f;
}

static void test_r14_archives() {
    namespace fs = std::filesystem;
    // job files from the synthetic panel_mm directory, under a "job1/" root
    std::vector<std::pair<std::string, std::string>> files;
    for (auto& e : fs::recursive_directory_iterator(D + "panel_mm")) {
        if (!e.is_regular_file()) continue;
        std::ifstream f(e.path(), std::ios::binary);
        std::string d((std::istreambuf_iterator<char>(f)), std::istreambuf_iterator<char>());
        std::string rel = fs::relative(e.path(), D + "panel_mm").generic_string();
        if (rel == "steps/pcb/layers/comp_+_bot/components") {
            // Allegro style: "???" part name, real part in PRP VALUE, device in PRP PART_NAME
            size_t q;
            while ((q = d.find(" RC0805-10K\n")) != std::string::npos) d.replace(q, 12, " ???\nPRP PART_NAME 'RESISTOR'\n");
            while ((q = d.find("PRP DESCRIPTION 'R0805 10k'\n")) != std::string::npos) d.erase(q, 28);
            while ((q = d.find("PRP MPN 'MPN-RC0805-10K'\n")) != std::string::npos) d.erase(q, 25);
        }
        files.push_back({"job1/" + rel, d});
    }
    CHECK(files.size() >= 10);
    std::vector<uint8_t> tar;
    tar_put(tar, "job1/", "", '5');
    for (auto& f : files) tar_put(tar, f.first, f.second);
    tar.resize(tar.size() + 1024, 0);
    const std::string tmp = (fs::temp_directory_path() / "pcbp_r14_odb").string();
    fs::create_directories(tmp);
    struct Case { std::string name; std::vector<uint8_t> data; };
    std::vector<Case> cases = {{"job.tar", tar}, {"job.zip", zip_stored(files)}};
    for (auto& c : cases) {
        const std::string path = tmp + "/" + c.name;
        CHECK(write_bin(path, c.data));
        std::string err;
        io::OdbJobInfo info;
        CHECKM(io::odb_scan(path, info, err), c.name + ": " + err);
        CHECK(info.root == "job1/");
        Project p;
        io::CadImportResult r;
        io::CadImportOptions o;
        CHECKM(io::import_odbpp(path, p, o, r, err), c.name + ": " + err);
        CHECKM(r.components == 6, c.name);
        const Component* r2 = p.find_ref("R2");
        CHECK(r2 && r2->number == "10k");                         // "???" ignored -> VALUE
        CHECK(p.parts.count("10k") && p.parts["10k"].description == "RESISTOR");
        CHECK(!p.parts.count("???"));
        CHECK(!has_warn(r, "PART_NAME"));
    }
    // hardening: traversal / absolute names fail the archive; safe names pass
    CHECK(io::archive_name_safe("job/steps/pcb/profile"));
    CHECK(io::archive_name_safe("./job/matrix/matrix"));
    CHECK(io::archive_name_safe("job/a..b/c"));
    CHECK(!io::archive_name_safe("../evil"));
    CHECK(!io::archive_name_safe("job/../../evil"));
    CHECK(!io::archive_name_safe("job\\..\\evil"));
    CHECK(!io::archive_name_safe("/etc/passwd"));
    CHECK(!io::archive_name_safe("C:/Windows/x"));
    CHECK(!io::archive_name_safe(""));
    for (int k = 0; k < 2; ++k) {
        std::vector<std::pair<std::string, std::string>> bad = {{"job1/matrix/matrix", "STEP {\n}\n"}, {"job1/../../x.txt", "boom"}};
        std::vector<uint8_t> data;
        if (k == 0) { for (auto& f : bad) tar_put(data, f.first, f.second); data.resize(data.size() + 1024, 0); }
        else data = zip_stored(bad);
        std::vector<io::ArchiveEntry> ents;
        std::string err;
        CHECK(!io::read_archive(data, ents, err));
        CHECKM(err.find("unsafe") != std::string::npos, err);
    }
    // truncated tar entry / corrupt gzip report errors, never crash
    {
        std::vector<uint8_t> t2(tar.begin(), tar.begin() + 512 + 100);
        std::vector<io::ArchiveEntry> ents;
        std::string err;
        CHECK(!io::read_tar(t2.data(), t2.size(), ents, err) || ents.size() <= 1);
        std::vector<uint8_t> gz = {0x1f, 0x8b, 8, 0, 0, 0, 0, 0, 0, 3, 0xff, 0xff, 0xff, 0xff, 0, 0, 0, 0, 0, 0, 0, 0};
        std::vector<uint8_t> out;
        CHECK(!io::gunzip(gz.data(), gz.size(), out, err));
    }
    std::error_code ec;
    fs::remove_all(tmp, ec);
}

